using System.IO.Compression;
using System.Text.Json;
using Jindan.Contracts;
namespace Jindan.Modules.Files;

// Virtual local folders organize immutable assets; move/rename never touches the
// user's source path. This is independent from the disabled live Drive adapter.
public sealed partial class FileDocument
{
    readonly TreeView folders = new() { Dock = DockStyle.Fill, HideSelection = false, Name = "LocalFolderTree" };
    string currentFolder = ""; bool rebuilding;
    readonly CancellationTokenSource folderLifetime = new(); long folderGeneration; bool folderDisposed;
    void InitializeFolders() { Grid.MultiSelect = true; var existing = NavigationPanel.Controls[0]; existing.Dock = DockStyle.Top; existing.Height = 140; NavigationPanel.Controls.Add(folders); folders.BringToFront(); folders.BeforeSelect += (_, e) => { if (!rebuilding && IsDirty) e.Cancel = true; }; folders.AfterSelect += async (_, e) => { if (rebuilding) return; await RunAsync(() => NavigateFolderAsync(e.Node?.Tag as string ?? "")); }; AddAction("새 로컬 폴더", CreateFolderDialogAsync); AddAction("폴더 이름 변경", RenameFolderDialogAsync); AddAction("빈 폴더 삭제", DeleteFolderDialogAsync); AddAction("상위 폴더", ParentFolderAsync); AddAction("선택 자료 일괄 삭제", TrashDialogAsync); AddAction("선택 자료 이동", MoveDialogAsync); AddAction("선택 자료 ZIP", ExportSelectionZipAsync); AddAction("현재 폴더 ZIP", ExportCurrentFolderZipAsync); InitializeGestures(); }
    protected override IReadOnlyList<WorkRecord> FilterRows(IReadOnlyList<WorkRecord> rows) => rows.Where(r => r.Fields.GetValueOrDefault("folderId", "") == currentFolder).OrderBy(r => r.Fields.GetValueOrDefault("title"), StringComparer.CurrentCultureIgnoreCase).ToArray();
    public override async Task RefreshAsync(string search = "") { if (Context.ProjectId is not null && !IsDirty) await RefreshFoldersAsync(); await base.RefreshAsync(search); SyncTiles(); }
    public override void SetContext(DocumentContext context) { if (IsDirty) throw new InvalidOperationException("변경 내용을 먼저 저장하세요."); archiveContextGeneration++; backFolders.Clear(); forwardFolders.Clear(); currentFolder = ""; base.SetContext(context); }
    async Task RefreshFoldersAsync() { var project = Context.ProjectId; var generation = ++folderGeneration; var rows = await Services.Data.ListAsync(Services.Actor, new("file-folders", project), folderLifetime.Token); if (IsDisposed || generation != folderGeneration || Context.ProjectId != project) return; rebuilding = true; folders.BeginUpdate(); try { folders.Nodes.Clear(); var top = folders.Nodes.Add("프로젝트 자료"); top.Tag = ""; var nodes = rows.ToDictionary(r => r.Id, r => new TreeNode(r.Fields["title"]) { Tag = r.Id }); foreach (var row in rows) { var parent = row.Fields.GetValueOrDefault("parentId", ""); (nodes.GetValueOrDefault(parent)?.Nodes ?? top.Nodes).Add(nodes[row.Id]); } top.Expand(); folders.SelectedNode = currentFolder.Length == 0 ? top : nodes.GetValueOrDefault(currentFolder) ?? top; currentFolder = folders.SelectedNode.Tag as string ?? ""; } finally { folders.EndUpdate(); rebuilding = false; } }
    protected override void Dispose(bool disposing) { if (disposing && !folderDisposed) { folderDisposed = true; folderGeneration++; folderLifetime.Cancel(); folderLifetime.Dispose(); } base.Dispose(disposing); }
    public Task<WorkRecord> CreateFolderAsync(string title, string parentId = "", CancellationToken ct = default) { if (Context.ProjectId is null) throw new InvalidOperationException("프로젝트를 선택하세요."); return Services.Data.SaveAsync(Services.Actor, new(null, "file-folders", Context.ProjectId, 0, new() { { "title", title }, { "parentId", parentId } }), ct); }
    public async Task<WorkRecord> RenameFolderAsync(string id, string title, CancellationToken ct = default) { var row = (await Services.Data.ListAsync(Services.Actor, new("file-folders", Context.ProjectId), ct)).Single(r => r.Id == id); var fields = new Dictionary<string, string>(row.Fields) { ["title"] = title }; return await Services.Data.SaveAsync(Services.Actor, new(row.Id, row.Kind, row.ProjectId, row.Revision, fields), ct); }
    async Task RenameFolderDialogAsync() { if (currentFolder.Length == 0) return; var current = (await Services.Data.ListAsync(Services.Actor, new("file-folders", Context.ProjectId))).Single(r => r.Id == currentFolder); using var dialog = new Form() { Text = "로컬 폴더 이름 변경", Width = 360, Height = 160, StartPosition = FormStartPosition.CenterParent }; var name = new TextBox() { Dock = DockStyle.Top, Text = current.Fields["title"] }; var save = new Button() { Dock = DockStyle.Bottom, Text = "변경", DialogResult = DialogResult.OK }; dialog.Controls.Add(name); dialog.Controls.Add(save); if (dialog.ShowDialog(this) == DialogResult.OK) { await RenameFolderAsync(currentFolder, name.Text); await RefreshAsync(); } }
    async Task DeleteFolderDialogAsync() { if (currentFolder.Length == 0) return; var row = (await Services.Data.ListAsync(Services.Actor, new("file-folders", Context.ProjectId))).Single(r => r.Id == currentFolder); if (MessageBox.Show(this, "빈 폴더를 휴지통 처리할까요? 자료가 있으면 삭제되지 않습니다.", "폴더 삭제 확인", MessageBoxButtons.YesNo) != DialogResult.Yes) return; await Services.Data.DeleteAsync(Services.Actor, row.Kind, row.Id, row.Revision, true); currentFolder = row.Fields.GetValueOrDefault("parentId", ""); await RefreshAsync(); }
    async Task ParentFolderAsync() { if (currentFolder.Length == 0 || IsDirty) return; var row = (await Services.Data.ListAsync(Services.Actor, new("file-folders", Context.ProjectId))).Single(r => r.Id == currentFolder); await NavigateFolderAsync(row.Fields.GetValueOrDefault("parentId", "")); }
    public async Task TrashSelectionAsync(IEnumerable<string> ids, bool confirmed, CancellationToken ct = default) { if (IsDirty) throw new InvalidOperationException("변경 내용을 먼저 저장하세요."); var selected = ids.Distinct().ToHashSet(); var rows = (await Services.Data.ListAsync(Services.Actor, new("files", Context.ProjectId), ct)).Where(r => selected.Contains(r.Id)).ToArray(); if (rows.Length != selected.Count) throw new InvalidOperationException("선택 자료를 다시 확인하세요."); foreach (var row in rows) await Services.Data.DeleteAsync(Services.Actor, row.Kind, row.Id, row.Revision, confirmed, ct); NewRecord(); await RefreshAsync(); }
    async Task TrashDialogAsync() { var ids = Grid.SelectedRows.Cast<DataGridViewRow>().Select(r => r.Tag).OfType<WorkRecord>().Select(r => r.Id).ToArray(); if (ids.Length > 0 && MessageBox.Show(this, $"선택 자료 {ids.Length}개를 휴지통 처리할까요? 원본은 보존됩니다.", "자료 삭제 확인", MessageBoxButtons.YesNo) == DialogResult.Yes) await TrashSelectionAsync(ids, true); }
    async Task CreateFolderDialogAsync() { using var dialog = new Form() { Text = "새 로컬 폴더", Width = 360, Height = 160, StartPosition = FormStartPosition.CenterParent }; var name = new TextBox() { Dock = DockStyle.Top }; var save = new Button() { Text = "생성", Dock = DockStyle.Bottom, DialogResult = DialogResult.OK }; dialog.Controls.Add(name); dialog.Controls.Add(save); dialog.AcceptButton = save; if (dialog.ShowDialog(this) == DialogResult.OK) { await CreateFolderAsync(name.Text, currentFolder); await RefreshAsync(); } }
    public async Task MoveToFolderAsync(string id, string target, CancellationToken ct = default) { if (IsDirty) throw new InvalidOperationException("변경 내용을 먼저 저장하세요."); var row = (await Services.Data.ListAsync(Services.Actor, new("files", Context.ProjectId), ct)).Single(r => r.Id == id); var fields = new Dictionary<string, string>(row.Fields) { ["folderId"] = target }; await Services.Data.SaveAsync(Services.Actor, new(row.Id, row.Kind, row.ProjectId, row.Revision, fields), ct); }
    async Task MoveDialogAsync() { if (Context.ProjectId is null) return; var selected = Grid.SelectedRows.Cast<DataGridViewRow>().Select(r => r.Tag).OfType<WorkRecord>().ToArray(); if (selected.Length == 0) return; var rows = await Services.Data.ListAsync(Services.Actor, new("file-folders", Context.ProjectId)); using var dialog = new Form() { Text = "선택 자료 이동 · 원본 보존", Width = 400, Height = 400, StartPosition = FormStartPosition.CenterParent }; var list = new ListBox() { Dock = DockStyle.Fill, DisplayMember = "Title" }; list.Items.Add(new FolderChoice("", "프로젝트 자료")); foreach (var r in rows) list.Items.Add(new FolderChoice(r.Id, r.Fields["title"])); list.SelectedIndex = 0; var move = new Button() { Text = "이동", Dock = DockStyle.Bottom, DialogResult = DialogResult.OK }; dialog.Controls.Add(list); dialog.Controls.Add(move); if (dialog.ShowDialog(this) == DialogResult.OK && list.SelectedItem is FolderChoice target) { foreach (var r in selected) await MoveToFolderAsync(r.Id, target.Id); NewRecord(); await RefreshAsync(); } }
    sealed record FolderChoice(string Id, string Title);
    public Task<string> ExportSelectionZipAsync(IEnumerable<string> ids, CancellationToken ct = default) => ExportSelectedZipCoreAsync(ids, ct);
    async Task ExportSelectionZipAsync() { var ids = Grid.SelectedRows.Cast<DataGridViewRow>().Select(r => r.Tag).OfType<WorkRecord>().Select(r => r.Id).ToArray(); Notice.Text = "새 사본 저장: " + await ExportSelectionZipAsync(ids); }
}
